/**
 * Authentication Middleware
 */

import { Response, NextFunction } from 'express';
import { AuthenticatedRequest, JwtPayload, UserRole, VerificationLevel, VERIFICATION_LEVEL_ORDER } from '../types';
import { verifyAccessToken, verifyConnectorToken } from '../services/jwt';
import { validateSession, updateSessionActivity } from '../services/session';
import { runWithTenantId } from '@secuura/shared';
import { UnauthorizedError, ForbiddenError, InsufficientVerificationError } from './errorHandler';
import { logger } from '../utils/logger';

// Test token prefix for E2E testing
const TEST_TOKEN_PREFIX = 'test_token_';

/**
 * Parse test token for E2E testing (non-production only)
 */
function parseTestToken(token: string): JwtPayload | null {
  // SECURITY: Never accept test tokens in production
  if (process.env.NODE_ENV === 'production') {
    return null;
  }
  // Require explicit opt-in for test tokens
  if (process.env.ENABLE_TEST_TOKENS !== 'true') {
    return null;
  }

  if (!token.startsWith(TEST_TOKEN_PREFIX)) {
    return null;
  }

  try {
    const base64Payload = token.slice(TEST_TOKEN_PREFIX.length);
    const payloadJson = Buffer.from(base64Payload, 'base64').toString('utf-8');
    const payload = JSON.parse(payloadJson);

    // Validate required fields
    if (!payload.sub || !payload.role) {
      return null;
    }

    // Check expiration
    if (payload.exp && payload.exp < Date.now()) {
      return null;
    }

    logger.debug('Parsed test token for E2E testing', { userId: payload.sub, role: payload.role });

    // Convert test token payload to JwtPayload format
    return {
      userId: payload.sub,
      role: payload.role as UserRole,
      email: payload.email || `test-${payload.sub}@secuura.test`,
      organizationId: payload.organizationId || 'test-org',
      verificationLevel: (payload.verificationLevel || 'BASIC') as VerificationLevel,
      sessionId: payload.sessionId || `test-session-${payload.sub}`,
      type: 'access' as const,
      iat: payload.iat || Date.now(),
      exp: payload.exp || Date.now() + 3600000,
    };
  } catch {
    return null;
  }
}

/**
 * KS-564 (Kam ruling 2026-08-06 — Option A): accept an interactive access token
 * OR a connector token, for ONE route only (`POST /api/users/stub`).
 *
 * Platform S issues certifications by recipient email, which needs the KS-74
 * INVITED-stub mint. S authenticates with an sk_ connector key, so its token is
 * `type: 'connector'` — which `authenticate()` rejects by design, and that is
 * why `/api/certifications/issue` has always 502'd with "Could not resolve
 * recipient via users/stub".
 *
 * Deliberately narrow, so this stays a scoped exception rather than a hole:
 *   - `authenticate()` itself is UNCHANGED — every other route keeps rejecting
 *     connector tokens, and `verifyAccessToken` keeps its `type: 'access'`
 *     invariant.
 *   - The connector branch verifies through `verifyConnectorToken`, which uses
 *     the same RS256-pinned `verifyToken` (no algorithm weakening).
 *   - Session checks are skipped ONLY on the connector branch, because
 *     connector tokens carry no sessionId by construction (revocation rides the
 *     10-minute exchange TTL instead).
 *   - Tenant comes from the VERIFIED token, never a header, and seeds the
 *     tenant GUC exactly as the interactive path does (KS-468).
 *   - The route's own role/scope gate still runs afterwards, so a connector
 *     without an accepted scope is still 403'd.
 *
 * @returns Express middleware that populates `req.user` from either token type.
 */
export function authenticateAccessOrConnector() {
  const interactive = authenticate();
  return async (req: AuthenticatedRequest, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;
    if (authHeader?.startsWith('Bearer ')) {
      const token = authHeader.split(' ')[1];
      let connector: ReturnType<typeof verifyConnectorToken> | null = null;
      try {
        connector = verifyConnectorToken(token);
      } catch {
        connector = null; // Not a connector token — fall through to the normal path.
      }
      if (connector) {
        req.user = connector as unknown as JwtPayload;
        logger.info('users/stub: connector token accepted (KS-564)', {
          connectorId: connector.userId,
          tenantId: connector.tenantId,
        });
        return runWithTenantId(connector.tenantId, () => next());
      }
    }
    return interactive(req, res, next);
  };
}

/**
 * Authenticate request using JWT
 */
export function authenticate(options: { required?: boolean } = { required: true }) {
  return async (req: AuthenticatedRequest, _res: Response, next: NextFunction) => {
    try {
      const authHeader = req.headers.authorization;

      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        if (options.required) {
          throw new UnauthorizedError('No token provided');
        }
        return next();
      }

      const token = authHeader.split(' ')[1];

      // Check for test token first (E2E testing support)
      const testPayload = parseTestToken(token);
      if (testPayload) {
        req.user = testPayload;
        req.sessionId = testPayload.sessionId;
        return runWithTenantId(testPayload.tenantId, () => next());
      }

      // Standard JWT verification
      const payload = verifyAccessToken(token);

      // Validate session is still active
      const isValidSession = await validateSession(payload.sessionId);
      if (!isValidSession) {
        throw new UnauthorizedError('Session has been invalidated');
      }

      // Update session activity
      await updateSessionActivity(payload.sessionId);

      // Attach user to request
      req.user = payload;
      req.sessionId = payload.sessionId;

      // KS-468: seed the tenant-GUC scope from the VERIFIED token. This
      // service is reachable through the gateway's unauthed /api/auth mount,
      // so no x-tenant-id header arrives and the app-level tenantGucContext()
      // ran before the token existed — without this wrap, post-auth reads of
      // fail-closed tables (users) return zero rows (phantom 404s, MFA state
      // reported disabled). runWithTenantId passes through when the token
      // carries no tenantId, which preserves today's behaviour for such tokens.
      runWithTenantId(payload.tenantId, () => next());
    } catch (error) {
      next(error);
    }
  };
}

/**
 * Require specific role(s)
 */
export function requireRole(...allowedRoles: UserRole[]) {
  return (req: AuthenticatedRequest, _res: Response, next: NextFunction) => {
    if (!req.user) {
      return next(new UnauthorizedError('Authentication required'));
    }

    if (!allowedRoles.includes(req.user.role)) {
      return next(new ForbiddenError(`Role ${req.user.role} is not authorized for this action`));
    }

    next();
  };
}

/**
 * Require minimum verification level
 */
export function requireVerificationLevel(minLevel: VerificationLevel) {
  return (req: AuthenticatedRequest, _res: Response, next: NextFunction) => {
    if (!req.user) {
      return next(new UnauthorizedError('Authentication required'));
    }

    const userLevelIndex = VERIFICATION_LEVEL_ORDER.indexOf(req.user.verificationLevel);
    const requiredLevelIndex = VERIFICATION_LEVEL_ORDER.indexOf(minLevel);

    if (userLevelIndex < requiredLevelIndex) {
      return next(new InsufficientVerificationError(minLevel, req.user.verificationLevel));
    }

    next();
  };
}

/**
 * Require user to own the resource or be admin
 */
export function requireOwnership(getResourceUserId: (req: AuthenticatedRequest) => string | undefined) {
  return (req: AuthenticatedRequest, _res: Response, next: NextFunction) => {
    if (!req.user) {
      return next(new UnauthorizedError('Authentication required'));
    }

    const resourceUserId = getResourceUserId(req);
    const isOwner = resourceUserId === req.user.userId;
    const isAdmin = ['SYSTEM_ADMIN', 'ORG_ADMIN', 'super_admin', 'SUPER_ADMIN'].includes(req.user.role);

    if (!isOwner && !isAdmin) {
      return next(new ForbiddenError('Not authorized to access this resource'));
    }

    next();
  };
}

/**
 * Require user to be in same organization
 */
export function requireSameOrganization(getResourceOrgId: (req: AuthenticatedRequest) => string | undefined) {
  return (req: AuthenticatedRequest, _res: Response, next: NextFunction) => {
    if (!req.user) {
      return next(new UnauthorizedError('Authentication required'));
    }

    const resourceOrgId = getResourceOrgId(req);
    const isSameOrg = resourceOrgId === req.user.organizationId;
    const isSystemAdmin = req.user.role === 'SYSTEM_ADMIN' || (req.user.role as string) === 'super_admin' || (req.user.role as string) === 'SUPER_ADMIN';

    if (!isSameOrg && !isSystemAdmin) {
      return next(new ForbiddenError('Not authorized to access resources from another organization'));
    }

    next();
  };
}

