/**
 * KS-468 — read-side fail-closed RLS: the auth service is reachable through
 * the gateway's UNAUTHED /api/auth mount, so no x-tenant-id header arrives
 * and the app-level tenantGucContext() runs before any token is verified.
 * Without an explicit seed, every post-auth read of a fail-closed table
 * (users) ran scope-less and returned zero rows — live symptoms: 404 from
 * GET /api/auth/me for an authenticated user, MFA status reported disabled,
 * and (pre-auth) the login MFA-challenge step reading the user as missing,
 * locking every MFA-enabled user out of login.
 *
 * Fixes under test:
 *  1. authenticate() now wraps next() in runWithTenantId(<verified token's
 *     tenantId>) — downstream handlers observe the tenant scope (both the
 *     standard-JWT and the E2E test-token branches).
 *  2. A token WITHOUT a tenantId claim seeds nothing (pass-through), same
 *     as before this change.
 *  3. KS-622: POST /api/auth/mfa/verify is RETIRED (410 Gone) and no longer
 *     performs any lookup at all — backup-code redemption moved to
 *     POST /api/auth/login, behind password verification. The SECURITY DEFINER
 *     lookup getUserByIdPreAuth is still the right choice for the pre-auth
 *     callers that remain (refresh, logout, and the wallet link path); this
 *     file's assertions below cover those, not the retired route.
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import type { AddressInfo } from 'node:net';
import type { Server } from 'node:http';
import express from 'express';
import { currentTenantId } from '@secuura/shared';

const state = vi.hoisted(() => ({
  tokenPayload: {
    userId: 'user-1',
    email: 'u@example.com',
    role: 'ISSUER',
    sessionId: 'sess-1',
    tenantId: 'tenant-guc-468' as string | undefined,
  },
  getUserByIdCalls: 0,
  getUserByIdPreAuthCalls: 0,
}));

vi.mock('../services/jwt', () => ({
  verifyAccessToken: vi.fn(() => ({ ...state.tokenPayload })),
}));

vi.mock('../services/session', () => ({
  validateSession: vi.fn(async () => true),
  updateSessionActivity: vi.fn(async () => undefined),
  createSession: vi.fn(async () => ({ id: 'sess-new' })),
  revokeSession: vi.fn(async () => undefined),
}));

vi.mock('../repositories/userRepo', () => ({
  // Simulates fail-closed RLS with no scope: the plain lookup sees nothing.
  getUserById: vi.fn(async () => {
    state.getUserByIdCalls++;
    return null;
  }),
  // The SECURITY DEFINER pre-auth lookup always resolves the row.
  getUserByIdPreAuth: vi.fn(async () => {
    state.getUserByIdPreAuthCalls++;
    return {
      id: 'user-1',
      email: 'u@example.com',
      role: 'ISSUER',
      status: 'ACTIVE',
      verificationLevel: 'BASIC',
      tenantId: 'tenant-guc-468',
      mfaEnabled: true,
      mfaSecret: 'JBSWY3DPEHPK3PXP',
      mfaBackupCodes: [],
    };
  }),
  updateUser: vi.fn(async () => null),
}));

import { authenticate } from '../middleware/authenticate';
import { mfaRoutes } from '../routes/mfa';
import { errorHandler } from '../middleware/errorHandler';

let server: Server;
let base: string;

beforeAll(async () => {
  const app = express();
  app.use(express.json());
  // Downstream probe: what tenant scope does a post-auth handler observe?
  app.get('/probe', authenticate(), (_req, res) => {
    res.json({ tenantInScope: currentTenantId() ?? null });
  });
  app.use('/api/auth/mfa', mfaRoutes);
  app.use(errorHandler);
  await new Promise<void>((resolve) => {
    server = app.listen(0, '127.0.0.1', resolve);
  });
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

afterAll(async () => {
  await new Promise((resolve) => server.close(resolve));
});

beforeEach(() => {
  state.tokenPayload.tenantId = 'tenant-guc-468';
  state.getUserByIdCalls = 0;
  state.getUserByIdPreAuthCalls = 0;
});

describe('KS-468: authenticate() seeds the tenant-GUC scope from the verified token', () => {
  it('downstream handlers observe the token tenantId as the ALS scope', async () => {
    const res = await fetch(`${base}/probe`, {
      headers: { authorization: 'Bearer real-jwt' },
    });
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({ tenantInScope: 'tenant-guc-468' });
  });

  it('a token without a tenantId claim seeds no scope (pass-through)', async () => {
    state.tokenPayload.tenantId = undefined;
    const res = await fetch(`${base}/probe`, {
      headers: { authorization: 'Bearer real-jwt' },
    });
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({ tenantInScope: null });
  });

  it('unauthenticated requests never reach the handler (contract unchanged)', async () => {
    const res = await fetch(`${base}/probe`);
    expect(res.status).toBe(401);
  });
});

describe('KS-468 + KS-622: /api/auth/mfa/verify is retired and touches nothing', () => {
  // KS-468's requirement — a pre-auth path must use the SECURITY DEFINER
  // lookup, or fail-closed RLS locks the user out — has NOT gone away. It moved.
  // /api/auth/mfa/verify was the pre-auth MFA-challenge step; KS-622 retired it
  // (410) because it redeemed a backup code with no proof of factor one, and
  // login now carries that redemption. getUserByIdPreAuth still has five other
  // callers (auth.ts refresh + two reset paths, wallet.ts, userRepo.ts), so the
  // definer carve-out is still load-bearing and still covered — just not here.
  //
  // What this asserts now is stronger than the old test: not merely that the
  // right lookup was used, but that NO lookup happens at all.
  it('answers 410 without any user lookup, definer or otherwise', async () => {
    const res = await fetch(`${base}/api/auth/mfa/verify`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ userId: 'user-1', code: '000000' }),
    });
    expect(res.status).toBe(410);
    expect(state.getUserByIdPreAuthCalls).toBe(0);
    expect(state.getUserByIdCalls).toBe(0);
  });
});
